contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: from address, target contract address caddr, array of tos, and value v.
    // We require _tos.length > 0 to match C.transfer's require, so the call may proceed to make calls.
    function run(address from, address caddr, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool returnedValue;
        try c.transfer(from, caddr, _tos, v) returns (bool r) {
            reverted = false;
            returnedValue = r;
        } catch {
            reverted = true;
            returnedValue = false;
        }

        // General rule: if the call did not revert then it must have returned true.
        // This asserts that whenever transfer completes successfully, it returns true.
        assert(!(reverted == false) || returnedValue == true);
    }

    receive() external payable {}
}

