contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // A minimal helper contract deployed within the checking environment is NOT allowed.
    // Instead we rely on calling a contract at address caddr that exposes a public view
    // counter() and a function to reset it via its own external behavior. However we cannot
    // deploy new contracts here. To keep within constraints, we instead require that
    // caddr is a contract that already implements a public getter callsCount() that
    // returns uint. We observe callsCount before and after calling c.transfer and assert
    // the difference equals _tos.length when transfer returns.

    // The test takes the external caddr and requires _tos.length>0. It reads callsCount()
    // before and after; if transfer returns (doesn't revert) then the difference equals _tos.length.

    // Note: This assumes the external caddr implements function callsCount() public view returns (uint);
    // The checker will consider arbitrary addresses; the property is general for those that do implement it.

    function run(address from, address caddr, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        // Read before counter via low-level staticcall to avoid interface declaration
        (bool okBefore, bytes memory dataBefore) = caddr.staticcall(abi.encodeWithSignature("callsCount()"));
        require(okBefore);
        uint before = abi.decode(dataBefore, (uint));

        bool reverted;
        bool ret;
        try c.transfer(from, caddr, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // Read after counter
        (bool okAfter, bytes memory dataAfter) = caddr.staticcall(abi.encodeWithSignature("callsCount()"));
        require(okAfter);
        uint after = abi.decode(dataAfter, (uint));

        // General rule: if transfer did not revert then it returned true and the external contract's
        // callsCount increased exactly by _tos.length (one call per _tos element).
        assert(reverted || (ret == true && after == before + _tos.length));
    }

    receive() external payable {}
}

